const $=id=>document.getElementById(id), params=new URLSearchParams(location.search);
let archive,issue,page=Number.parseInt(params.get('page'),10)||1;
const query=params.get('q');if(query)$('back').href='./?'+new URLSearchParams({q:query});
function render(){page=Math.max(1,Math.min(issue.pages,page));$('page-number').value=page;$('page-number').max=issue.pages;$('count').textContent=' / '+issue.pages;$('prev').disabled=page===1;$('next').disabled=page===issue.pages;const pdf=issue.file+'#page='+page;for(const id of ['pdf','pdf-top'])$(id).href=pdf;$('download').href=issue.file;const text=archive.pages.find(p=>p.date===issue.date&&p.page===page);$('text').textContent=text?.text||'No extracted text is available for this page.';const img=$('page-image');img.hidden=false;img.alt='Piedmont Post, '+issue.date+', page '+page;img.src='pages/'+issue.date+'/'+page+'.jpg';$('reader-status').textContent='Loading page '+page+'…';document.title='Page '+page+' · '+issue.date+' · Piedmont Post';params.set('page',String(page));history.replaceState(null,'','?'+params);}
$('page-image').addEventListener('load',()=>{$('reader-status').textContent='Page '+page+' of '+issue.pages;});$('page-image').addEventListener('error',()=>{$('page-image').hidden=true;$('reader-status').textContent='Page preview unavailable. Use the original PDF link above.';});$('prev').addEventListener('click',()=>{page--;render();});$('next').addEventListener('click',()=>{page++;render();});$('jump').addEventListener('submit',e=>{e.preventDefault();const val=Number.parseInt($('page-number').value,10);if(Number.isFinite(val)){page=val;render();}});document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowLeft'&&page>1){page--;render();}if(e.key==='ArrowRight'&&page<issue?.pages){page++;render();}});
try{const response=await fetch('search-index.json');if(!response.ok)throw Error('Archive unavailable');archive=await response.json();issue=archive.issues.find(i=>i.date===params.get('issue'));if(!issue)throw Error('Issue not found');$('date').textContent=new Date(issue.date+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});render();}catch(error){$('date').textContent='Issue unavailable';$('reader-status').textContent='Return to the archive and select an issue.';console.error(error);}
